"""Binary Tree Postorder Traversal — reversed "root-right-left" preorder.

Time: O(n)   Space: O(h)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def postorderTraversal(self, root) -> List[int]:
        if not root:
            return []
        out, stack = [], [root]
        while stack:
            node = stack.pop()
            out.append(node.val)
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        return out[::-1]
